using System;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "BalanceOfReckoningOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/BalanceOfReckoningOmenData")]
public class BalanceOfReckoningOmenData : EndOfTurnOmenData
{
	[Header("Balance Of Reckoning Omen Data")]
	[SerializeField]
	private SoulHeat soulHeat;

	[SerializeField]
	private OmenLogic omenLogic;

	[Header("Even Action")]
	[SerializeField]
	private ReliefDefaultEffectAction reliefAction;

	[SerializeField]
	private int reliefAmount;

	[Header("Odd Action")]
	[SerializeField]
	private AfflictionDefaultEffectAction afflictionAction;

	[SerializeField]
	private int afflictionAmount;

	[SerializeField]
	private OmenLogicActionFace boostOmenLogicActionFace;

	public override Action GetOmenAction(OmenInstance omenInstance)
	{
		return delegate
		{
			omenInstance.ActivateOmenFeedback();
			if (soulHeat.SoulHeatCounter % 2 == 0)
			{
				omenLogic.ActivateOmen(afflictionAction, afflictionAmount, null, null);
				boostOmenLogicActionFace.OmenLogic.ActivateOmen(boostOmenLogicActionFace.ActionFace.BattleAction, boostOmenLogicActionFace.ActionFace.ActionValue, null, null);
			}
			else
			{
				omenLogic.ActivateOmen(reliefAction, reliefAmount, null, null);
			}
		};
	}

	public override string OmenConvertedDescription()
	{
		string arg = afflictionAction.GetActionDescription(afflictionAmount) + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + boostOmenLogicActionFace.ActionFace.BattleAction.GetActionDescription(boostOmenLogicActionFace.ActionFace.ActionValue);
		string actionDescription = reliefAction.GetActionDescription(reliefAmount);
		return GetEndOfPlayerTurnLocalizedDescription() + "\n" + Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedEvenOddSoulHeat(), arg, actionDescription);
	}
}
